                for _ in range(k):
                    r, c = c, -r
                pts.append((r, c))
            mr, mc = min(r for r, c in pts), min(c for r, c in pts)
            variants.add(tuple(sorted((r - mr, c - mc) for r, c in pts)))

    out = [row[:] for row in grid]
