def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1

    # The object color is the rarest color in the grid.
    color = min(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == color]

    rmin = min(r for r, c in points)
    cmin = min(c for r, c in points)
    shape = [(r - rmin, c - cmin) for r, c in points]
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1

    out = [row[:] for row in grid]
    for r0 in range(h - sh + 1):
        for c0 in range(w - sw + 1):
            cells = [(r0 + r, c0 + c) for r, c in shape]
            if all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = color
    return out
